	public void FFChangeOnGraphic(PrintWriter print_writer, String whichGraphic,String Command,int which_side) throws InterruptedException {
		switch(Command.toUpperCase()) {
		case "OUT":
			switch(whichGraphic.toUpperCase()) {
			case "NAMESUPER-PLAYER":
				break;
			case "HOWOUT":
				TimeUnit.MILLISECONDS.sleep(300);
				break;	
			}
			break;
		case "IN":
			switch(whichGraphic.toUpperCase()) {
			case "BATBALLSUMMARY_SCORECARD": case "BATBALLSUMMARY_BOWLINGCARD": case "BATBALLSUMMARY_MATCHSUMMARY": case "POINTSTABLE":
			case "TEAMLINEUP":
				animationProcess(print_writer, "BG_Change", "START", "RSWS", 3);
				animationProcess(print_writer, "Logo_Change", "START", "RSWS", 3);
				animationProcess(print_writer, "Header_Change", "START", "RSWS", 3);
				animationProcess(print_writer, "Data_Change", "START", "RSWS", 3);
				break;
			case "FFPLAYERPROFILE": case "PLAYERPROFILEBALL":
				animationProcess(print_writer, "BG_Change", "START", "RSWS", 3);
//				animationProcess(print_writer, "Trans_In", "START", "RSWS", 2);
				animationProcess(print_writer, "Logo_Change", "START", "RSWS", 3);
				animationProcess(print_writer, "Data_Change", "START", "RSWS", 3);
				break;	
			}
			break;
		case "CHANGE_ON":
			switch(whichGraphic.toUpperCase()) {
			case "BATBALLSUMMARY_SCORECARD": case "BATBALLSUMMARY_BOWLINGCARD": case "BATBALLSUMMARY_MATCHSUMMARY": case "POINTSTABLE": case "TEAMLINEUP":
				switch(whichGraphic.toUpperCase()) {
				case "BATBALLSUMMARY_SCORECARD":
					print_writer.println("LAYER3*EVEREST*TREEVIEW*Main$DataAllGrp$Side" + which_side + "*FUNCTION*SELECTOR SET NUMBER 0;");
					break;
				case "BATBALLSUMMARY_BOWLINGCARD":
					print_writer.println("LAYER3*EVEREST*TREEVIEW*Main$DataAllGrp$Side" + which_side + "*FUNCTION*SELECTOR SET NUMBER 1;");
					break;
				case "BATBALLSUMMARY_MATCHSUMMARY":
					print_writer.println("LAYER3*EVEREST*TREEVIEW*Main$DataAllGrp$Side" + which_side + "*FUNCTION*SELECTOR SET NUMBER 2;");
					break;
				case "POINTSTABLE":
					print_writer.println("LAYER3*EVEREST*TREEVIEW*Main$DataAllGrp$Side" + which_side + "*FUNCTION*SELECTOR SET NUMBER 9;");
					break;
				case "TEAMLINEUP":
					print_writer.println("LAYER3*EVEREST*TREEVIEW*Main$DataAllGrp$Side" + which_side + "*FUNCTION*SELECTOR SET NUMBER 4;");
					break;
				}
				animationProcess(print_writer, "BG_Change", "RESET", "RSWS", 3);
				animationProcess(print_writer, "Logo_Change", "RESET", "RSWS", 3);
				animationProcess(print_writer, "Header_Change", "RESET", "RSWS", 3);
				TimeUnit.MILLISECONDS.sleep(600);
				print_writer.println("LAYER3*EVEREST*STAGE*DIRECTOR*Data_In STOP;");
				print_writer.println("LAYER3*EVEREST*STAGE*DIRECTOR*Data_In SHOW 501;");
				TimeUnit.MILLISECONDS.sleep(600);
				print_writer.println("LAYER3*EVEREST*STAGE*DIRECTOR*Data_Change STOP;");
				animationProcess(print_writer, "Data_Change", "SHOW 0", "RSWS", 3);
				
				break;
			case "FFPLAYERPROFILE": case "PLAYERPROFILEBALL":
				print_writer.println("LAYER3*EVEREST*TREEVIEW*Main$DataAllGrp$Side" + which_side + "*FUNCTION*SELECTOR SET NUMBER 10;");
				animationProcess(print_writer, "BG_Change", "RESET", "RSWS", 3);
				animationProcess(print_writer, "Logo_Change", "RESET", "RSWS", 3);
//				animationProcess(print_writer, "Header_Change", "RESET", "RSWS", 3);
				animationProcess(print_writer, "Data_Change", "RESET", "RSWS", 3);
				break;	
			}
			break;
		}
	}
	
	public void processAnimation(PrintWriter print_writer, String animationName,String animationCommand, String which_broadcaster)
	{
		switch(which_broadcaster.toUpperCase()) {
		case "DOAD_VIZ": case "NEPAL_T20": case "RSWS":
			print_writer.println("-1 RENDERER*FRONT_LAYER*STAGE*DIRECTOR*"+ animationName + " " + animationCommand +" \0");
			break;
		case "DOAD_EVEREST":
			print_writer.println("LAYER1*EVEREST*STAGE*DIRECTOR*" + animationName + " " + animationCommand + ";");
			
			break;
		}
		
	}
	
	public void animationProcess(PrintWriter print_writer, String animationName,String animationCommand, String which_broadcaster,int which_layer)
	{
		switch(which_broadcaster.toUpperCase()) {
		case "RSWS":
			switch(which_layer) {
			case 1:
				print_writer.println("LAYER1*EVEREST*STAGE*DIRECTOR*" + animationName + " " + animationCommand + ";");
				break;
				
			case 2:
				print_writer.println("LAYER2*EVEREST*STAGE*DIRECTOR*" + animationName + " " + animationCommand + ";");
				//print_writer.println("LAYER2*EVEREST*STAGE*DIRECTOR*LOOP START;");	
				break;
			case 3:
				print_writer.println("LAYER3*EVEREST*STAGE*DIRECTOR*" + animationName + " " + animationCommand + ";");
				//print_writer.println("LAYER2*EVEREST*STAGE*DIRECTOR*LOOP START;");	
				break;	
			}
			break;
		}
		
	}
	public String resetInfobarAnimation(PrintWriter print_writer,String which_frame) throws InterruptedException, IOException {
		
			switch(which_frame.toUpperCase()) {
			case "FF_FRAME":
				if(infobar.isInfobar_on_screen() == true) {
					print_writer.println("LAYER1*EVEREST*SCENE LAYER_RENDER 1;");
					print_writer.println("LAYER2*EVEREST*SCENE LAYER_RENDER 0;");
					print_writer.println("LAYER3*EVEREST*SCENE LAYER_RENDER 0;");
					AnimateOutGraphics(print_writer, "FF_OUT");
					which_graphic_on_screen = "SCOREBUG";
				}
				break;
			case "LT_FRAME":
				if(infobar.isInfobar_on_screen() == true) {
					print_writer.println("LAYER1*EVEREST*SCENE LAYER_RENDER 1;");
					print_writer.println("LAYER2*EVEREST*SCENE LAYER_RENDER 0;");
					print_writer.println("LAYER3*EVEREST*SCENE LAYER_RENDER 0;");
					AnimateOutGraphics(print_writer, "LT_OUT");
					which_graphic_on_screen = "SCOREBUG";
				}
				break;
			}
		return "";
	}
