			print_writer.println("LAYER1*EVEREST*SCENE LAYER_RENDER 0;");
			print_writer.println("LAYER2*EVEREST*SCENE LAYER_RENDER 1;");
			print_writer.println("LAYER2*EVEREST*STAGE*DIRECTOR*In SHOW 32.0;");
			print_writer.println("LAYER1*EVEREST*GLOBAL SNAPSHOT_PATH C:/Temp/Preview.tga;");
			print_writer.println("LAYER1*EVEREST*GLOBAL SNAPSHOT 1920 1080;");
			TimeUnit.SECONDS.sleep(1);
			print_writer.println("LAYER2*EVEREST*STAGE*DIRECTOR*In SHOW 0.0;");
			print_writer.println("LAYER1*EVEREST*SCENE LAYER_RENDER 1;");
			print_writer.println("LAYER2*EVEREST*SCENE LAYER_RENDER 0;");
