	public void populateNameSuperPlayer(PrintWriter print_writer,String viz_scene, String captainWicketKeeper, int playerId, CricketService cricketService, MatchAllData match, String broadcaster,int whichside) throws InterruptedException
	{
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else {
			String cap_wic_data = "";
			
			print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$LogoAll*FUNCTION*SELECTOR SET NUMBER 0;");
			print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$BgAll*FUNCTION*SELECTOR SET NUMBER 0;");
			print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$LogoBaseAll*FUNCTION*SELECTOR SET NUMBER 0;");
			
			Player player = cricketService.getAllPlayer().stream().filter(plyr -> plyr.getPlayerId() == playerId).findAny().orElse(null);
			Team team = cricketService.getTeams().stream().filter(tm -> tm.getTeamId() == player.getTeamId()).findAny().orElse(null);
			
			switch(captainWicketKeeper.toUpperCase())
			{
			case CricketUtil.CAPTAIN:
				cap_wic_data = captainWicketKeeper.toUpperCase() + ", " + team.getTeamName1();
				break;
			case CricketUtil.WICKET_KEEPER:
				cap_wic_data = "WICKET-KEEPER" + ", " + team.getTeamName1();
				break;	
			case "PLAYER OF THE MATCH":
				cap_wic_data = captainWicketKeeper.toUpperCase();
				break;
			case "PLAYER OF THE TOURNAMENT":
				cap_wic_data = captainWicketKeeper.toUpperCase();
				break;
			case "PLAYER OF THE SERIES":
				cap_wic_data = captainWicketKeeper.toUpperCase();
				break;	
			case CricketUtil.PLAYER:
				cap_wic_data = team.getTeamName1();
				break;
			case "CAPTAIN-WICKETKEEPER":
				cap_wic_data = "CAPTAIN & WICKET-KEEPER" + ", " + team.getTeamName1();
				break;
			}
			
			print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$NameSuper*CONTAINER SET ACTIVE 1;"
					+ "LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$NameSuper$Data$Position*CONTAINER SET ACTIVE 0;"
					+ "LAYER2*EVEREST*TREEVIEW*Main$BgGrp$Side" + whichside + "$MainBaseGRP$Color2*CONTAINER SET ACTIVE 1;"
					+ "LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$LogoGrp$Side" + whichside + "$Logo*TEXTURE1 SET TEXTURE_PATH " + logo_path + 
					team.getTeamBadge() + CricketUtil.PNG_EXTENSION + ";"
					+ "LAYER2*EVEREST*TREEVIEW*Main$BgGrp$Side" + whichside + "$MainBaseGRP$Color1*TEXTURE1 SET TEXTURE_PATH " + team_color +
					team.getTeamBadge() + CricketUtil.PNG_EXTENSION + ";"
					+ "LAYER2*EVEREST*TREEVIEW*Main$BgGrp$Side" + whichside + "$MainBaseGRP$Color2*TEXTURE1 SET TEXTURE_PATH " + team_color2 +
					team.getTeamBadge() + CricketUtil.PNG_EXTENSION + ";"
					+ "LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$NameSuper$Data$Name"
					+ "$TextName*TEXTURE2 SET TEXTURE_PATH " + text_color1 + team.getTeamBadge() + CricketUtil.PNG_EXTENSION + ";"
					+ "LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$NameSuper$Data$Name"
					+ "$TextSecondName*TEXTURE2 SET TEXTURE_PATH " + text_color1 + team.getTeamBadge() + CricketUtil.PNG_EXTENSION + ";"
					+ "LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$NameSuper$Data$Team"
					+ "$TextTeam*TEXTURE2 SET TEXTURE_PATH " + team_text_color2 + team.getTeamBadge() + CricketUtil.PNG_EXTENSION + ";"
					+ "LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$NameSuper$Data$Team"
					+ "$BG*TEXTURE2 SET TEXTURE_PATH " + team_color2 + team.getTeamBadge() + CricketUtil.PNG_EXTENSION + ";"
					+ "LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$NameSuper$Data$Name"
					+ "$TextName*GEOMETRY*TEXT_UTF8 SET TEXT_UTF8 " + (player.getFirstname() != null ? player.getFirstname() : "") + ";"
					+ "LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$NameSuper$Data$Name"
					+ "$TextSecondName*GEOMETRY*TEXT_UTF8 SET TEXT_UTF8 " + (player.getSurname() != null ? player.getSurname() : "") + ";"
					+ "LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$NameSuper$Data$Team"
					+ "$TextTeam*GEOMETRY*TEXT_UTF8 SET TEXT_UTF8 " + cap_wic_data + ";"
					+ "LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "*CONTAINER SET ACTIVE 1;");
			
//			print_writer.println("LAYER2*EVEREST*STAGE*DIRECTOR*Data_Change STOP;");
//			print_writer.println("LAYER2*EVEREST*STAGE*DIRECTOR*Data_Change SHOW 0.0;");
//			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.png In 1.500 \0");
//			TimeUnit.MILLISECONDS.sleep(200);
		}
	}
