	public void populateLtPointsTable(PrintWriter print_writer,String viz_sence_path,List<LeagueTeam> point_table,List<Team> teams, MatchAllData match, String selectedbroadcaster) throws InterruptedException 
	{
		int row_id=0,omo=0;
		String cont = "";
		
		print_writer.println("-1 RENDERER*TREE*$Main$All$TopPart$SubHeaderGrp$SubHeaderText$txt_TeamName*GEOM*TEXT SET " + "POINTS TABLE" + "\0");
		print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$DataAll$SubHeadGrp$txt_PointsHead*GEOM*TEXT SET " + "PTS" + "\0");
		
		for(int i = 0; i <= point_table.size()-1; i++) {
			row_id = row_id + 1;
			
			if(match.getSetup().getHomeTeam().getTeamName4().equalsIgnoreCase(point_table.get(i).getTeamName().toUpperCase())  
					|| match.getSetup().getAwayTeam().getTeamName4().equalsIgnoreCase(point_table.get(i).getTeamName().toUpperCase())) {
				cont = "$Highlight";
				omo=1;
			}else {
				cont = "$Dehighlight";
				omo=0;
			}
			
			print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$DataAll$SelectBowlerNumber$Row" + row_id + 
					"$RowAnim$SelectHighlight*FUNCTION*Omo*vis_con SET " + omo + "\0");
			
			if(point_table.get(i).getQualifiedStatus().trim().equalsIgnoreCase("")) {
				print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$DataAll$SelectBowlerNumber$Row" + row_id + 
						"$RowAnim$SelectHighlight"+ cont +"$AllData$txt_Rank*GEOM*TEXT SET " + row_id + "\0");
			}else {
				print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$DataAll$SelectBowlerNumber$Row" + row_id + 
						"$RowAnim$SelectHighlight"+ cont +"$AllData$txt_Rank*GEOM*TEXT SET " + "Q" + "\0");
			}
			
			for(Team team : teams) {
				if(team.getTeamName4().equalsIgnoreCase(point_table.get(i).getTeamName())) {
					print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$DataAll$SelectBowlerNumber$Row" + row_id + 
							"$RowAnim$SelectHighlight"+ cont +"$AllData$txt_TeamName*GEOM*TEXT SET " + team.getTeamName2() + "\0");
				}
			}
			
			print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$DataAll$SelectBowlerNumber$Row" + row_id + 
					"$RowAnim$SelectHighlight"+ cont +"$AllData$txt_PlayValue*GEOM*TEXT SET " + point_table.get(i).getPlayed() + "\0");
			print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$DataAll$SelectBowlerNumber$Row" + row_id + 
					"$RowAnim$SelectHighlight"+ cont +"$AllData$txt_WinValue*GEOM*TEXT SET " + point_table.get(i).getWon() + "\0");
			print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$DataAll$SelectBowlerNumber$Row" + row_id + 
					"$RowAnim$SelectHighlight"+ cont +"$AllData$txt_PointsValue*GEOM*TEXT SET " + point_table.get(i).getPoints() + "\0");
			print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$DataAll$SelectBowlerNumber$Row" + row_id + 
					"$RowAnim$SelectHighlight"+ cont +"$AllData$txt_NRRValue*GEOM*TEXT SET " + point_table.get(i).getNetRunRate() + "\0");
			
			print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$DataAll$SelectBowlerNumber$Row" + row_id + 
					"$RowAnim$SelectHighlight"+ cont +"$AllData$SelectCurrentStatus*ACTIVE SET 0 \0");
			print_writer.println("-1 RENDERER*TREE*$Main$All$TopPart$LogoMotion$TeamLogo*ACTIVE SET 0 \0");
			
		}
		print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_sence_path + " C:/Temp/Preview.png In 1.900 \0");
		TimeUnit.MILLISECONDS.sleep(200);
	}
	
