	public void populateSplit(PrintWriter print_writer,String viz_scene,int whichInning,int splitValue,int whichside, MatchAllData match, String broadcaster) throws InterruptedException
	{
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else {
		
			print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$LogoAll*FUNCTION*SELECTOR SET NUMBER 0;");
			
			print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$BgAll*FUNCTION*SELECTOR SET NUMBER 0;");
			print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$LogoBaseAll*FUNCTION*SELECTOR SET NUMBER 0;");
			
			print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "*CONTAINER SET ACTIVE 1;");
			print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$PlayerStats*CONTAINER SET ACTIVE 1;");
			
			for(Inning inn : match.getMatch().getInning()) {
				if (inn.getInningNumber() == whichInning) {
					
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$LogoAll$LogoGrp$Side" + whichside + "$Logo*TEXTURE1 SET TEXTURE_PATH " + logo_path + 
							inn.getBatting_team().getTeamBadge().toUpperCase() + CricketUtil.PNG_EXTENSION + ";");
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$LogoAll$LogoGrp$Side" + whichside + "$LeftTesture*TEXTURE1 SET TEXTURE_PATH " + 
							team_color2 + inn.getBatting_team().getTeamBadge().toUpperCase() + CricketUtil.PNG_EXTENSION + ";");
					
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$BgAll$BgGrp$Side" + whichside + "$MainBaseGRP$Color1*TEXTURE1 SET TEXTURE_PATH " + team_color + 
							inn.getBatting_team().getTeamBadge().toUpperCase() + CricketUtil.PNG_EXTENSION + ";");
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$BgAll$BgGrp$Side" + whichside + "$MainBaseGRP$Color2*TEXTURE1 SET TEXTURE_PATH " + team_color2 + 
							inn.getBatting_team().getTeamBadge().toUpperCase() + CricketUtil.PNG_EXTENSION + ";");
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$BallsPer$Score$base*TEXTURE1 SET TEXTURE_PATH " 
							+ team_color2 + inn.getBatting_team().getTeamBadge().toUpperCase() + CricketUtil.PNG_EXTENSION + ";");
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$BallsPer$Score$TextName*TEXTURE1 SET TEXTURE_PATH " 
							+ team_text_color2 + inn.getBatting_team().getTeamBadge().toUpperCase() + CricketUtil.PNG_EXTENSION + ";");
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$BallsPer$Score$TextName2*TEXTURE1 SET TEXTURE_PATH " 
							+ team_text_color2 + inn.getBatting_team().getTeamBadge().toUpperCase() + CricketUtil.PNG_EXTENSION + ";");
					
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$BallsPer$Stats$base*TEXTURE1 SET TEXTURE_PATH " 
							+ team_color2 + inn.getBatting_team().getTeamBadge().toUpperCase() + CricketUtil.PNG_EXTENSION + ";");
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$BallsPer$Stats$Stat1" + 
							"$Stat*TEXTURE2 SET TEXTURE_PATH " + team_text_color + inn.getBatting_team().getTeamBadge().toUpperCase() + CricketUtil.PNG_EXTENSION + ";");
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$BallsPer$Stats$Stat1" + 
							"$Data*TEXTURE2 SET TEXTURE_PATH " + team_text_color2 + inn.getBatting_team().getTeamBadge().toUpperCase() + CricketUtil.PNG_EXTENSION + ";");
					
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$BallsPer$Name" + 
							"$TextName*TEXTURE2 SET TEXTURE_PATH " + team_text_color + inn.getBatting_team().getTeamBadge().toUpperCase() + CricketUtil.PNG_EXTENSION + ";");
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$BallsPer$Name" + 
							"$TextSecondName*TEXTURE2 SET TEXTURE_PATH " + team_text_color + inn.getBatting_team().getTeamBadge().toUpperCase() + CricketUtil.PNG_EXTENSION + ";");
					
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$BallsPer$Name"
							+ "$TextName*GEOMETRY*TEXT_UTF8 SET TEXT_UTF8 " + inn.getBatting_team().getTeamName1().toUpperCase() + ";");
					
					if(inn.getTotalWickets() >=10) {
						print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$BallsPer$Score"
								+ "$TextName*GEOMETRY*TEXT_UTF8 SET TEXT_UTF8 " + inn.getTotalRuns() + ";");
					}else {
						print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$BallsPer$Score"
								+ "$TextName*GEOMETRY*TEXT_UTF8 SET TEXT_UTF8 " + inn.getTotalRuns() + "-" + inn.getTotalWickets() + ";");
					}
					
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$BallsPer$Score$TextName2"
							+ "*GEOMETRY*TEXT_UTF8 SET TEXT_UTF8 " + CricketFunctions.OverBalls(inn.getTotalOvers(), inn.getTotalBalls()) + ";");
					
					if(splitValue == 30) {
						print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$BallsPer$Name"
								+ "$TextSecondName*GEOMETRY*TEXT_UTF8 SET TEXT_UTF8 " + "BALLS PER THIRTY" + ";");
						print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$BallsPer$Stats$Stat1"
								+ "$Stat*GEOMETRY*TEXT_UTF8 SET TEXT_UTF8 " + "THIRTIES" + ";");
						
					}else {
						print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$BallsPer$Name"
								+ "$TextSecondName*GEOMETRY*TEXT_UTF8 SET TEXT_UTF8 " + "BALLS PER FIFTY" + ";");
						print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$BallsPer$Stats$Stat1"
								+ "$Stat*GEOMETRY*TEXT_UTF8 SET TEXT_UTF8 " + "FIFTIES" + ";");
					}
					
					for(int split_id=1;split_id<=7;split_id++) {
						print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$BallsPer$Stats$Stat" + (split_id + 1) + 
								"*CONTAINER SET ACTIVE 0;");
						print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$BallsPer$Stats$Stat" + (split_id + 1) + 
								"$Stat*TEXTURE2 SET TEXTURE_PATH " + team_text_color + inn.getBatting_team().getTeamBadge().toUpperCase() + CricketUtil.PNG_EXTENSION + ";");
						print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$BallsPer$Stats$Stat" + (split_id + 1) + 
								"$Data*TEXTURE2 SET TEXTURE_PATH " + team_text_color2 + inn.getBatting_team().getTeamBadge().toUpperCase() + CricketUtil.PNG_EXTENSION + ";");
			    	}
					
				    for (int i = 0; i < CricketFunctions.getSplit(whichInning, splitValue,match,match.getEventFile().getEvents()).size(); i++) {
				    	int row_id = i + 1;
				    	for(int split_id=1;split_id<=7;split_id++) {
					    	if(split_id <= CricketFunctions.getSplit(whichInning, splitValue,match,match.getEventFile().getEvents()).size()) {
					    		
					    		print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$BallsPer$Stats$Stat" + (row_id + 1) + 
										"*CONTAINER SET ACTIVE 1;");
					    		
					    		print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$BallsPer$Stats$Stat" + 
										(row_id + 1) + "$Stat*GEOMETRY*TEXT_UTF8 SET TEXT_UTF8 " + row_id + ";");
								print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side" + whichside + "$BallsPer$Stats$Stat" + (row_id + 1) + 
										"$Data*GEOMETRY*TEXT_UTF8 SET TEXT_UTF8 " + CricketFunctions.getSplit(whichInning,splitValue,match,
												match.getEventFile().getEvents()).get(i) + ";");
					    	}
				    	}
			        }
				}
			}
		}
	}	
	public void populateComparision(PrintWriter print_writer,String viz_scene, MatchAllData match, String broadcaster) throws InterruptedException
	{
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else if (match.getMatch().getInning() == null) {
			this.status = "ERROR: Comparision's inning is null";
		} else {
			
//			print_writer.println("LAYER2*EVEREST*STAGE*DIRECTOR*Data_Change STOP;");
//			print_writer.println("LAYER2*EVEREST*STAGE*DIRECTOR*Data_Change SHOW 0.0;");
			
			print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$BgAll*FUNCTION*SELECTOR SET NUMBER 1;");
			print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$LogoBaseAll*FUNCTION*SELECTOR SET NUMBER 1;");
			print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$LogoAll*FUNCTION*SELECTOR SET NUMBER 1;");
			
			print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side1*CONTAINER SET ACTIVE 1;");
			print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side1$Comparison*CONTAINER SET ACTIVE 1;");
			
			print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$BgAll$Bg2Grp$Side1$MainBaseGRP$Color1*TEXTURE1 SET TEXTURE_PATH " + team_color + 
					"GEN" + CricketUtil.PNG_EXTENSION + ";");
			print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$BgAll$Bg2Grp$Side1$MainBaseGRP$Color2*TEXTURE1 SET TEXTURE_PATH " + team_color2 + 
					"GEN" + CricketUtil.PNG_EXTENSION + ";");
			
			print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side1$Comparison$Data$Name$TextName*TEXTURE2 SET TEXTURE_PATH " 
					+ team_text_color + "GEN" + CricketUtil.PNG_EXTENSION + ";");
			print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side1$Comparison$Data$Name$TextSecondName*TEXTURE2 SET TEXTURE_PATH " 
					+ team_text_color + "GEN" + CricketUtil.PNG_EXTENSION + ";");
			print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side1$Comparison$Data$Name2$TextName*TEXTURE2 SET TEXTURE_PATH " 
					+ team_text_color + "GEN" + CricketUtil.PNG_EXTENSION + ";");
			print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side1$Comparison$Data$Name2$TextSecondName*TEXTURE2 SET TEXTURE_PATH " 
					+ team_text_color + "GEN" + CricketUtil.PNG_EXTENSION + ";");
			
			for(Inning inn : match.getMatch().getInning()) {
				if(inn.getInningNumber() == 2 & inn.getIsCurrentInning().equalsIgnoreCase("YES")) {
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$LogoAll$Logo2Grp$Side1$HomeLogoGrp$Logo*TEXTURE1 SET TEXTURE_PATH " + logo_path + 
							inn.getBowling_team().getTeamBadge().toUpperCase() + CricketUtil.PNG_EXTENSION + ";");
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$LogoAll$Logo2Grp$Side1$HomeLogoGrp$LeftTesture*TEXTURE1 SET TEXTURE_PATH " + team_color2 + 
							inn.getBowling_team().getTeamBadge().toUpperCase() + CricketUtil.PNG_EXTENSION + ";");
					
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$LogoAll$Logo2Grp$Side1$AwayLogoGrp$Logo*TEXTURE1 SET TEXTURE_PATH " + logo_path + 
							inn.getBatting_team().getTeamBadge().toUpperCase() + CricketUtil.PNG_EXTENSION + ";");
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$LogoAll$Logo2Grp$Side1$AwayLogoGrp$LeftTesture*TEXTURE1 SET TEXTURE_PATH " + team_color2 + 
							inn.getBatting_team().getTeamBadge().toUpperCase() + CricketUtil.PNG_EXTENSION + ";");
					
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side1$Comparison$Data$Name$BG*TEXTURE1 SET TEXTURE_PATH " + team_color + 
							inn.getBowling_team().getTeamBadge().toUpperCase() + CricketUtil.PNG_EXTENSION + ";");
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side1$Comparison$Data$Name$TextThirdName*TEXTURE2 SET TEXTURE_PATH " + team_text_color + 
							inn.getBowling_team().getTeamBadge().toUpperCase() + CricketUtil.PNG_EXTENSION + ";");
					
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side1$Comparison$Data$Name2$BG*TEXTURE1 SET TEXTURE_PATH " + team_color + 
							inn.getBatting_team().getTeamBadge().toUpperCase() + CricketUtil.PNG_EXTENSION + ";");
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side1$Comparison$Data$Name2$TextThirdName*TEXTURE2 SET TEXTURE_PATH " + team_text_color + 
							inn.getBatting_team().getTeamBadge().toUpperCase() + CricketUtil.PNG_EXTENSION + ";");
					
					
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side1$Comparison$Data$Name"
							+ "$TextName*GEOMETRY*TEXT_UTF8 SET TEXT_UTF8 " + inn.getBowling_team().getTeamName2().toUpperCase() + ";");
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side1$Comparison$Data$Name"
							+ "$TextSecondName*GEOMETRY*TEXT_UTF8 SET TEXT_UTF8 " + inn.getBowling_team().getTeamBadge().toUpperCase() + ";");
					
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side1$Comparison$Data$Name2"
							+ "$TextName*GEOMETRY*TEXT_UTF8 SET TEXT_UTF8 " + inn.getBatting_team().getTeamName2().toUpperCase() + ";");
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side1$Comparison$Data$Name2"
							+ "$TextSecondName*GEOMETRY*TEXT_UTF8 SET TEXT_UTF8 " + inn.getBatting_team().getTeamBadge().toUpperCase() + ";");
					
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side1$Comparison$Data$Team"
							+ "$TextTeam*GEOMETRY*TEXT_UTF8 SET TEXT_UTF8 " + "AFTER " + CricketFunctions.OverBalls(inn.getTotalOvers(), inn.getTotalBalls()) + " OVERS" + ";");
					
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side1$Comparison$Data$Name"
							+ "$TextThirdName*GEOMETRY*TEXT_UTF8 SET TEXT_UTF8 " + CricketFunctions.compareInningData(match, "-", 1, match.getEventFile().getEvents()) + ";");
					
					print_writer.println("LAYER2*EVEREST*TREEVIEW*Main$RESTALL_GRP$DATA_ALLGrp$Side1$Comparison$Data$Name2"
							+ "$TextThirdName*GEOMETRY*TEXT_UTF8 SET TEXT_UTF8 " + CricketFunctions.compareInningData(match, "-", 2, match.getEventFile().getEvents()) + ";");
					
				}
			}
		}	
	}
