						print_writer.println("-1 RENDERER*TREE*$Main$All$AllDataGrp$BattingData$DataAll$SelectBowlerNumber$Row" + row_id + "$RowAnim$SelectHighlight" + cont_name + 
								"$txt_BowlerName*GEOM*TEXT SET " + boc.getPlayer().getTicker_name() + "\0");
						
