	public void populateThisSeries(PrintWriter print_writer, String viz_scene,int Playerid,String TypeofProfile,List<Tournament> this_series,MatchAllData match, String broadcaster) throws InterruptedException {
		
		if (match == null) {
			this.status = "ERROR: Match is null";
		} else {
			
			double strike_rate = 0 , economy_rate=0;
			int k=0;
		
			List<BestStats> top_batsman_beststats = new ArrayList<BestStats>();
			List<BestStats> top_bowler_beststats = new ArrayList<BestStats>();
			for(Tournament tourn : this_series) {
				for(BestStats bs : tourn.getBatsman_best_Stats()) {
					top_batsman_beststats.add(bs);
				}
				for(BestStats bfig : tourn.getBowler_best_Stats()) {
					top_bowler_beststats.add(bfig);
				}
			}
			
			Collections.sort(top_batsman_beststats, new CricketFunctions.PlayerBestStatsComparator());
			Collections.sort(top_bowler_beststats, new CricketFunctions.PlayerBestStatsComparator());
			
			print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position*FUNCTION*Omo*vis_con SET 15 \0");
			
			print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$HeaderGrp$HeaderText$Text2*GEOM*TEXT SET " + "THIS SERIES" +" \0");
			
			for(int i = 0; i <= this_series.size() - 1 ; i++) {
				if(this_series.get(i).getPlayerId() == Playerid) {
					
					if(this_series.get(i).getPlayer().getTeamId() == match.getSetup().getHomeTeamId()) {
						print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$Rest_Base_ALL$DataBase_Logo_Grp$DataBand$LogoGRP$Logo"
								+ "$TeamLogo*TEXTURE*IMAGE SET " + logo_path + match.getSetup().getHomeTeam().getTeamName4() + "\0");
					}else {
						print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$Rest_Base_ALL$DataBase_Logo_Grp$DataBand$LogoGRP$Logo"
								+ "$TeamLogo*TEXTURE*IMAGE SET " + logo_path + match.getSetup().getAwayTeam().getTeamName4() + "\0");
					}
					
					print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$HeaderGrp$HeaderText$Text*GEOM*TEXT SET " + this_series.get(i).getPlayer().getFull_name() +" \0");
					
					
					switch(TypeofProfile.toUpperCase()) {
					case CricketUtil.BATSMAN:
						print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$DataAll$SubDataGrp$Row1$RowAnim$1$StatHeadHrp$StatHead1$Text*GEOM*TEXT SET " + "MATCHES" +" \0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$DataAll$SubDataGrp$Row1$RowAnim$1$StatHeadHrp$StatHead2$Text*GEOM*TEXT SET " + "RUNS" +" \0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$DataAll$SubDataGrp$Row1$RowAnim$1$StatHeadHrp$StatHead3$Text*GEOM*TEXT SET " + "BEST" +" \0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$DataAll$SubDataGrp$Row1$RowAnim$1$StatHeadHrp$StatHead4$Text*GEOM*TEXT SET " + "S/R" +" \0");
						
						print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$DataAll$SubDataGrp$Row2$RowAnim$1$StatHeadHrp$StatHead1"
								+ "$Text*GEOM*TEXT SET " + this_series.get(i).getMatches() +" \0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$DataAll$SubDataGrp$Row2$RowAnim$1$StatHeadHrp$StatHead2"
								+ "$Text*GEOM*TEXT SET " + this_series.get(i).getRuns() +" \0");
						
						if(this_series.get(i).getBallsFaced() == 0 || this_series.get(i).getRuns()== 0) {
							print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$DataAll$SubDataGrp$Row2$RowAnim$1$StatHeadHrp$StatHead4"
									+ "$Text*GEOM*TEXT SET " + "-" +" \0");
						}else {
							strike_rate = this_series.get(i).getRuns() * 100;
							strike_rate = strike_rate/this_series.get(i).getBallsFaced();
							DecimalFormat df = new DecimalFormat("0.0");
							print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$DataAll$SubDataGrp$Row2$RowAnim$1$StatHeadHrp$StatHead4"
									+ "$Text*GEOM*TEXT SET " + df.format(strike_rate) +" \0");
						}
						 
						for(int j=0;j<= top_batsman_beststats.size()-1;j++) {
							if(top_batsman_beststats.get(j).getPlayerId() == Playerid) {
								if(k == 0) {
									k += 1;
									if(top_batsman_beststats.get(j).getBestEquation() % 2 == 0) {
										print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$DataAll$SubDataGrp$Row2$RowAnim$1$StatHeadHrp$StatHead3"
												+ "$Text*GEOM*TEXT SET " + top_batsman_beststats.get(j).getBestEquation()/2 +" \0");
									}else {
										print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$DataAll$SubDataGrp$Row2$RowAnim$1$StatHeadHrp$StatHead3"
												+ "$Text*GEOM*TEXT SET " + (top_batsman_beststats.get(j).getBestEquation()-1) / 2 + "*" +" \0");
									}
									break;
								}
							}else {
								print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$DataAll$SubDataGrp$Row2$RowAnim$1$StatHeadHrp$StatHead3"
										+ "$Text*GEOM*TEXT SET " + "-" +" \0");
							}
						}
						break;
					case CricketUtil.BOWLER:
						print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$DataAll$SubDataGrp$Row1$RowAnim$1$StatHeadHrp$StatHead1$Text*GEOM*TEXT SET " + "MATCHES" +" \0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$DataAll$SubDataGrp$Row1$RowAnim$1$StatHeadHrp$StatHead2$Text*GEOM*TEXT SET " + "WICKETS" +" \0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$DataAll$SubDataGrp$Row1$RowAnim$1$StatHeadHrp$StatHead3$Text*GEOM*TEXT SET " + "BEST" +" \0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$DataAll$SubDataGrp$Row1$RowAnim$1$StatHeadHrp$StatHead4$Text*GEOM*TEXT SET " + "ECONOMY" +" \0");
						
						print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$DataAll$SubDataGrp$Row2$RowAnim$1$StatHeadHrp$StatHead1"
								+ "$Text*GEOM*TEXT SET " + this_series.get(i).getMatches() +" \0");
						print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$DataAll$SubDataGrp$Row2$RowAnim$1$StatHeadHrp$StatHead2"
								+ "$Text*GEOM*TEXT SET " + this_series.get(i).getWickets() +" \0");
						
						if(this_series.get(i).getBallsBowled() == 0 || this_series.get(i).getRunsConceded() == 0) {
							print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$DataAll$SubDataGrp$Row2$RowAnim$1$StatHeadHrp$StatHead4"
									+ "$Text*GEOM*TEXT SET " + "-" +" \0");
						}else {
							economy_rate = (this_series.get(i).getRunsConceded()*1.00) /this_series.get(i).getBallsBowled();
							economy_rate = economy_rate * 6;
							DecimalFormat df = new DecimalFormat("0.00");
							print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$DataAll$SubDataGrp$Row2$RowAnim$1$StatHeadHrp$StatHead4"
									+ "$Text*GEOM*TEXT SET " + df.format(economy_rate) +" \0");
						}
						
						for(int j=0;j<= top_bowler_beststats.size()-1;j++) {
							if(top_bowler_beststats.get(j).getPlayerId() == Playerid) {
								if(k == 0) {
									k += 1;
									if(top_bowler_beststats.get(j).getBestEquation() % 1000 > 0) {
										print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$DataAll$SubDataGrp$Row2$RowAnim$1$StatHeadHrp$StatHead3"
												+ "$Text*GEOM*TEXT SET " + ((top_bowler_beststats.get(j).getBestEquation() / 1000) +1) + "-" + (1000 - (top_bowler_beststats.get(j).getBestEquation() % 1000)) +" \0");
									}
									else if(top_bowler_beststats.get(j).getBestEquation() % 1000 < 0) {
										print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$DataAll$SubDataGrp$Row2$RowAnim$1$StatHeadHrp$StatHead3"
												+ "$Text*GEOM*TEXT SET " + (top_bowler_beststats.get(j).getBestEquation() / 1000) + "-" + Math.abs(top_bowler_beststats.get(j).getBestEquation()) +" \0");
									}
									break;
								}
							}else if(top_bowler_beststats.get(j).getPlayerId() != Playerid) {
								print_writer.println("-1 RENDERER*TREE*$Main$All$Lt_Position$PalyerCareer$DataAll$SubDataGrp$Row2$RowAnim$1$StatHeadHrp$StatHead3"
										+ "$Text*GEOM*TEXT SET " + "-" +" \0");
							}
						}
						break;
					}
				}
			}
			print_writer.println("-1 RENDERER PREVIEW SCENE*" + viz_scene + " C:/Temp/Preview.png In 1.500\0");
			TimeUnit.MILLISECONDS.sleep(200);
		}
	}
	
